<script>
// ── Owner notice: the Daily e-mail cannot be prepared (owner decision D-G4, 2026-10-09) ───────────────────────────────
// The page never reads the notice store (email_delivery/… is server-only under the Rules). It asks the owner-authorized
// route — POST /api/daily-snapshot/run with action: "notice" (delivery R7 contract: status, deliverable, code, notice,
// noticeState, clearState) — and decides from the BUSINESS state the server confirmed, never from a stored or synthesized
// record. Three outcomes, kept distinct:
//   "active"   the server confirmed the business has no usable name: the Daily is blocked → the alert is shown
//   "clear"    the server confirmed the name is present (and any stored notice is cleared or was never there) → hidden
//   "unknown"  anything else — a failed / refused / unreachable read, a 503 (registry or notice store unavailable, a failed
//              clear), a reply of another shape, another business state — changes NOTHING: a visible alert stays visible,
//              nothing new appears, and the page is unaffected. A failed read is never "resolved".
(function () {
  "use strict";
  var MESSAGE_HE = "לא ניתן להכין את הסיכום היומי כי חסר שם העסק. נדרש תיקון פרטי העסק.";
  var NOTICE_ENDPOINT = "/api/daily-snapshot/run";
  var OWNER_ROLES = Object.freeze(["owner", "super_owner"]);
  function isRecord(x) { return x !== null && typeof x === "object" && !Array.isArray(x); }
  /** The request body of the authorized read. `action` is mandatory: without it the same route is a manual Daily send. */
  function noticeRequest(tenantId, bizId) { return { tenantId: tenantId, bizId: bizId, action: "notice" }; }
  /** Whether this page may ask at all: an owner / super_owner with a live (tenantId, bizId) selection, not in demo mode. */
  function shouldAsk(role, tenantId, bizId, demo) {
    return OWNER_ROLES.indexOf(role) >= 0 && typeof tenantId === "string" && tenantId !== "" && typeof bizId === "string" && bizId !== "" && demo !== true;
  }
  /**
   * Decide from one reply. `status` is the HTTP status (null = no reply), `body` the parsed JSON (or null).
   *   { kind: "active", businessDate, runs }  200 ok, deliverable === false, code === "business_name_unavailable", for THIS business
   *   { kind: "clear" }                        200 ok, deliverable === true, for THIS business
   *   { kind: "unknown", reason }              everything else
   * A stored record (body.notice) may only decorate an active decision (its date / count); it never decides.
   */
  function decide(status, body, tenantId, bizId) {
    if (status !== 200 || !isRecord(body)) return { kind: "unknown", reason: status === null ? "no_reply" : "http_" + status };
    if (body.status !== "ok" || body.tenantId !== tenantId || body.bizId !== bizId) return { kind: "unknown", reason: "shape_or_identity" };
    if (typeof body.noticeState !== "string" || typeof body.clearState !== "string") return { kind: "unknown", reason: "shape" };  // not the R7 contract
    if (body.deliverable === true) return { kind: "clear" };
    if (body.deliverable === false && body.code === "business_name_unavailable") {
      var rec = isRecord(body.notice) && body.notice.code === "business_name_unavailable" ? body.notice : null;
      return { kind: "active", businessDate: rec && typeof rec.businessDate === "string" ? rec.businessDate : null, runs: rec && Number.isInteger(rec.runs) && rec.runs > 0 ? rec.runs : null };
    }
    return { kind: "unknown", reason: "other_business_state" };
  }
  /** The displayed states are kept PER BUSINESS (a switch away and back never loses what was confirmed for a business). */
  function key(tenantId, bizId) { return String(tenantId) + "\u0000" + String(bizId); }
  function stateFor(states, tenantId, bizId) { var s = isRecord(states) ? states[key(tenantId, bizId)] : null; return isRecord(s) ? s : { kind: "idle" }; }
  /** The next map of displayed states after one decision for (tenantId, bizId): "unknown" leaves that business's state as it is. */
  function next(states, decision, tenantId, bizId) {
    var map = isRecord(states) ? states : {};
    var cur = stateFor(map, tenantId, bizId), out = Object.assign({}, map);
    if (!isRecord(decision) || decision.kind === "unknown") { if (cur.kind !== "idle") out[key(tenantId, bizId)] = Object.assign({}, cur, { lastReadFailed: true }); return out; }
    if (decision.kind === "clear") { out[key(tenantId, bizId)] = { kind: "clear" }; return out; }
    if (decision.kind === "active") { out[key(tenantId, bizId)] = { kind: "active", businessDate: decision.businessDate, runs: decision.runs }; return out; }
    return out;
  }
  /** Whether the alert is shown for the selected business. */
  function visible(states, tenantId, bizId) { return stateFor(states, tenantId, bizId).kind === "active"; }
  window.MarjinDailyNotice = Object.freeze({ MESSAGE_HE: MESSAGE_HE, NOTICE_ENDPOINT: NOTICE_ENDPOINT, OWNER_ROLES: OWNER_ROLES, noticeRequest: noticeRequest, shouldAsk: shouldAsk, decide: decide, next: next, stateFor: stateFor, visible: visible });
